<script lang="ts">
 import {languageOverrides} from "./localization";
 import {translator} from './i18n';import {intervalRange,type IntervalRequest,type IntervalChoice} from './report-interval';import {Check,X} from '@lucide/svelte';
 export let request:IntervalRequest;export let language:'ru'|'ro'|"en";export let onclose:()=>void;
 const initial=request.to.slice(0,7)||request.current;let choice:IntervalChoice={mode:'month',year:Number(initial.slice(0,4)),quarter:Math.ceil(Number(initial.slice(5,7))/3),month:Number(initial.slice(5,7)),day:request.to,yearToDate:false,quarterToDate:false,monthToDate:false};let error='';$:t=translator(language,$languageOverrides);$:range=(()=>{try{return intervalRange(choice,request.current);}catch{return null;}})();
 function apply(){if(!range){error=t('Укажите корректный интервал.','Indicați un interval valid.');return;}request.onapply(range.from,range.to);onclose();}
</script>
<div class="interval-dialog"><p>{t('Устанавливаемый интервал','Interval selectat')}: {range?range.from+' — '+range.to:'—'}</p><label class="check-row"><input type="radio" value="current" bind:group={choice.mode}/>{t('Текущий расчётный период','Perioada curentă de calcul')}</label>
<div class="interval-row"><label><input type="radio" value="year" bind:group={choice.mode}/>{t('Год','An')}</label><input type="number" min="1" max="9999" bind:value={choice.year}/></div>
<div class="interval-row"><label><input type="radio" value="quarter" bind:group={choice.mode}/>{t('Квартал','Trimestru')}</label><select bind:value={choice.quarter}>{#each [1,2,3,4] as quarter}<option value={quarter}>{quarter}</option>{/each}</select><label><input type="checkbox" bind:checked={choice.yearToDate} disabled={choice.mode!=='quarter'&&choice.mode!=='month'}/>{t('С начала года','De la începutul anului')}</label></div>
<div class="interval-row"><label><input type="radio" value="month" bind:group={choice.mode}/>{t('Месяц','Lună')}</label><input type="month" value={`${String(choice.year).padStart(4,'0')}-${String(choice.month).padStart(2,'0')}`} onchange={e=>{const [year,month]=e.currentTarget.value.split('-').map(Number);choice={...choice,year,month};}}/><label><input type="checkbox" bind:checked={choice.quarterToDate} disabled={choice.mode!=='month'||choice.yearToDate}/>{t('С начала квартала','De la începutul trimestrului')}</label></div>
<div class="interval-row"><label><input type="radio" value="day" bind:group={choice.mode}/>{t('День','Zi')}</label><input type="date" bind:value={choice.day}/><label><input type="checkbox" bind:checked={choice.monthToDate} disabled={choice.mode!=='day'}/>{t('С начала месяца','De la începutul lunii')}</label></div>
{#if error}<p role="alert">{error}</p>{/if}<footer><button class="button" disabled={!range} onclick={apply}><Check size={16}/>OK</button><button class="button secondary" onclick={onclose}><X size={16}/>{t('Отмена','Anulează')}</button></footer></div>
<style>.interval-dialog{padding:16px;display:flex;flex-direction:column;gap:12px}.interval-row{display:grid;grid-template-columns:110px 170px minmax(0,1fr);gap:12px;align-items:center}label{display:flex;gap:7px;align-items:center}input[type=number],input[type=date],input[type=month],select{height:36px;box-sizing:border-box;min-width:0;width:100%}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}</style>
